import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Atalho PJe Mídias","description":"","frontmatter":{"title":"Atalho PJe Mídias","id":"eproc-midias-link","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.0.9","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-midias-link"}]]},"headers":[],"relativePath":"funcionalidades/eproc-midias-link.md","filePath":"funcionalidades/eproc-midias-link.md"}'),i={name:"funcionalidades/eproc-midias-link.md"};function n(c,a,d,l,t,p){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="atalho-pje-midias" tabindex="-1">Atalho PJe Mídias <a class="header-anchor" href="#atalho-pje-midias" aria-label="Permalink to &quot;Atalho PJe Mídias&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Coloca um ícone de câmera ao lado do número do processo que abre o PJe Mídias, já pesquisando o processo, em nova aba. Assim você chega às gravações de audiência sem copiar e colar o número.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, ao lado do número do processo.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo no eproc.</li><li>Em segundo plano, o eploc consulta o PJe Mídias para saber se há gravações daquele processo.</li><li>Se houver, o ícone de câmera mostra a quantidade de audiências. Passe o mouse para ver o resumo (&quot;Acessar 2 audiências no PJe Mídias&quot;, por exemplo).</li><li>Clique no ícone: o PJe Mídias abre numa nova aba, com o processo pesquisado.</li></ol><p>Quando a consulta não consegue confirmar a quantidade, o ícone aparece sem número e o balão convida a verificar (&quot;Verificar se há audiências no PJe Mídias&quot;). Quando a consulta confirma que não há gravações, o ícone não aparece.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A consulta usa a sua sessão no PJe Mídias (<code>midias.pje.jus.br</code>). Se ela expirar, o eploc tenta entrar de novo automaticamente. Se não conseguir, o ícone aparece sem número.</li><li>Para fazer essa consulta, o número do processo é enviado ao PJe Mídias, como aconteceria numa pesquisa feita à mão. Veja <a href="./../privacidade">Privacidade e dados</a>.</li></ul>',12)]))}const h=e(i,[["render",n]]);export{m as __pageData,h as default};
